module counter_assertions #(parameter W = 4) (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [W-1:0] cnt
);

    // Property: Counter must increment by exactly 1 when enabled.
    // Ensures no skipping or jumping occurs during active cycles.
    property p_cnt_increment;
        @(posedge clk) disable iff (rst)
            en |-> (cnt == $past(cnt) + 1'b1);
    endproperty

    // Property: Counter must hold value when disabled.
    // Ensures no unintended state changes occur when not enabled.
    property p_cnt_hold;
        @(posedge clk) disable iff (rst)
            !en |-> (cnt == $past(cnt));
    endproperty

    // Assertion: Enforce increment behavior
    ap_cnt_increment: assert property (p_cnt_increment);

    // Assertion: Enforce hold behavior
    ap_cnt_hold: assert property (p_cnt_hold);

endmodule

// Assertion 1: State Encoding Validity
// Ensures the state register always holds one of the four defined legal values.
property p_state_legal;
    @(posedge clk) disable iff (rst) state inside {RED, RED_YELLOW, GREEN, YELLOW};
endproperty
assert_property(p_state_legal);

// Assertion 2: Transition Order
// Ensures the light never transitions directly from RED to GREEN.
// Captures the invariant that RED must be followed by RED_YELLOW.
property p_no_red_to_green;
    @(posedge clk) disable iff (rst) (state == RED |-> ##1 state != GREEN);
endproperty
assert_property(p_no_red_to_green);

module sync_fifo_buggy_assertions #(parameter WIDTH = 8, parameter DEPTH = 4) (
    input  wire             clk,
    input  wire             rst,
    input  wire             wr_en,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output reg  [WIDTH-1:0] rd_data,
    output reg              full,
    output reg              empty,
    output reg  [1:0]       count
);

    // Property 1: Full is asserted exactly when count equals DEPTH
    property p_full_correct;
        @(posedge clk) disable iff (rst)
        full |-> (count == DEPTH);
    endproperty

    // Property 2: Empty is asserted exactly when count equals 0
    property p_empty_correct;
        @(posedge clk) disable iff (rst)
        empty |-> (count == 0);
    endproperty

    // Property 3: Count never exceeds DEPTH
    property p_count_bound;
        @(posedge clk) disable iff (rst)
        count <= DEPTH;
    endproperty

    // Assertions
    assert property (p_full_correct) else $error("Full assertion failed: full=%b count=%d", full, count);
    assert property (p_empty_correct) else $error("Empty assertion failed: empty=%b count=%d", empty, count);
    assert property (p_count_bound) else $error("Count bound violated: count=%d > DEPTH=%d", count, DEPTH);

endmodule

module rr_arbiter_assertions #(parameter N = 4) (
    input  wire         clk,
    input  wire         rst,
    input  wire [N-1:0] req,
    input  wire [N-1:0] grant
);

    property p_onehot_or_zero;
        @(posedge clk) $onehot0(grant);
    endproperty

    property p_grant_subset_req;
        @(posedge clk) (grant & ~req) == 0;
    endproperty

    assert property (p_onehot_or_zero);
    assert property (p_grant_subset_req);

endmodule

